SET NAMES utf8mb4;

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Дентални импланти',
'<p>Денталните импланти са изкуствени зъбни корени, които се поставят в челюстната кост с цел възстановяване на липсващите зъби функционално и естетично. Пригодността за лечение с импланти се определя чрез съвместна оценка на костната структура, здравето на венците, общото здравословно състояние и индивидуалните нужди.</p>
<h2>Какво е дентален имплант?</h2>
<p>Имплантът е изкуствен корен, поставен в челюстната кост така, че да замести корена на загубения зъб. Задачата му е да поддържа от костта конструкцията, която ще бъде изработена върху него. Върху импланта може да се постави единична корона, мост, носещ няколко зъба, или неподвижна конструкция, обхващаща цялата челюст.</p>
<p>Коя конструкция е подходяща, се определя според броя липсващи зъби, позицията на празнината, оклузалните отношения и естетичните очаквания. Сред възможните материали може да се обсъди и <a href="/bg/zirkonyum-dis-kaplama/">циркониева корона</a>.</p>
<p><img src="/assets/uploads/images/ts01-tek-dis-implant-kesiti.webp" alt="Срез, показващ имплант на единичен зъб в челюстната кост" loading="lazy"  /></p>
<p><img src="/assets/uploads/images/ts01-implant-ustu-kuron-parcalari.webp" alt="Разглобен изглед на частите на корона върху имплант" loading="lazy"  /></p>
<h2>За кого може да се обсъжда?</h2>
<p>Възможността за имплант може да се обсъжда при хора с липса на един или повече зъби, недоволни от настоящата си протеза или търсещи неподвижно решение вместо подвижна протеза. Пригодността не зависи от един критерий:</p>
<ul>
<li>Брой липсващи зъби, позиция на празнината и състояние на съседните зъби</li>
<li>Обем и качество на челюстната кост</li>
<li>Здраве на венците и ежедневни навици за орална хигиена</li>
<li>Общо здравословно състояние, приемани лекарства и тютюнопушене</li>
</ul>
<p>Тези теми могат да бъдат оценени заедно само след преглед и необходимата образна диагностика. За сравнителен поглед върху другите възможности при липсващи зъби вижте нашето <a href="/bg/implant/">ръководство за лечение с импланти</a>.</p>
<h2>Оценка преди импланта</h2>
<p>Планирането не се изчерпва с измерване на празнината. Заедно се разглеждат здравната история, редовно приеманите лекарства, състоянието на венците, обемът и качеството на костта, оклузалните отношения и тютюнопушенето. Чрез необходимите образни методи се изследват височината и ширината на костта и анатомичните съседства.</p>
<p>Протетичното планиране също се прави на този етап: позицията на импланта се определя според дизайна на конструкцията, която ще дойде върху него. След оценката Ви се съобщават възможностите и предполагаемите етапи; преди прегледа не се поема ангажимент за брой импланти, срок или резултат.</p>
<h2>Как протича лечението?</h2>
<ol>
<li><strong>Преглед и образна диагностика</strong> — клинични находки и рентгенова оценка.</li>
<li><strong>Планиране</strong> — определяне на позицията и броя на имплантите и дизайна на конструкцията.</li>
<li><strong>Поставяне на импланта</strong> — хирургичен етап под местна упойка.</li>
<li><strong>Период на зарастване</strong> — времето, необходимо за срастване на импланта с костта (остеоинтеграция).</li>
<li><strong>Протетична конструкция</strong> — снемане на отпечатък и поставяне на конструкцията.</li>
<li><strong>Контролни прегледи</strong> — редовно клинично и при нужда рентгеново проследяване.</li>
</ol>
<p>Продължителността на етапите зависи от състоянието на костта, приложения метод и това дали е необходима допълнителна процедура.</p>
<p><img src="/assets/uploads/images/ts01-implant-tedavi-asamalari.webp" alt="Четирите етапа на лечението с дентални импланти" loading="lazy"  /></p>
<h2>Недостиг на кост</h2>
<p>Увеличаване на костния обем не е необходимо при всеки пациент. Когато костният обем се прецени като недостатъчен, може да се обсъди присаждане или повдигане на пода на синуса; тази нужда се определя след образната диагностика. За подробности относно тези процедури и хирургичния процес като цяло вижте страницата <a href="/bg/agiz-cerrahisi-uygulamalari/">орална хирургия</a>.</p>
<p><img src="/assets/uploads/images/ts01-kemik-hacmi-karsilastirmasi.webp" alt="Сравнение между достатъчен и недостатъчен обем на челюстната кост" loading="lazy"  /></p>
<h2>Дългосрочен успех</h2>
<p>Дългосрочният успех на денталните импланти се влияе от много фактори: правилен подбор на случая, планиране, орална хигиена, тютюнопушене, общо здравословно състояние, дизайн на конструкцията и редовни прегледи. Част от тези фактори са в ръцете на лекаря, а част — в ежедневните навици; затова периодът след лечението е неделима част от планирането.</p>
<h2>Грижа след имплантирането</h2>
<p>Препоръките, дадени след процедурата, са индивидуални и спазването им влияе пряко върху зарастването. Тъй като тъканите около импланта също могат да се възпалят, ежедневното четкане, интерденталното почистване и редовните прегледи не бива да се пренебрегват.</p>
<p>Ако забележите нарастващ оток, непреминаваща болка, кървене на венците, разхлабване на конструкцията или променено усещане при захапка, препоръчително е да си запазите контролен час.</p>
<h2>Често задавани въпроси</h2>
<p><strong>Колко продължава лечението с импланти?</strong><br>Срокът се определя от етапите, а не от една процедура. Периодът на зарастване, необходим за срастването на импланта с костта, зависи от състоянието на костта и приложения метод. Върху срока влияе и дали е нужна допълнителна процедура. Предполагаемите етапи се съобщават след прегледа и образната диагностика; ангажимент за фиксиран срок не се поема.</p>
<p><strong>Има ли възрастова граница за импланти?</strong><br>Няма горна възрастова граница; определящи са не възрастта, а костната и венечната опора и общото здравословно състояние. При долната граница се очаква растежът на челюстите да е завършил. Пригодността се определя при прегледа.</p>
<p><strong>Усеща ли се болка по време на процедурата?</strong><br>Поставянето на импланта се извършва под местна упойка и целта е комфорт. Възможно е усещане за натиск и вибрация. Тъй като личното преживяване може да е различно, категорична гаранция за безболезненост не се дава.</p>
<p><strong>Пуша, възможен ли е имплант?</strong><br>Тютюнопушенето е сред факторите, които могат да повлияят неблагоприятно върху зарастването около импланта и дългосрочния резултат. Само по себе си може да не е абсолютна пречка; рискът обаче се обсъжда открито с пациента и планирането се съобразява с него.</p>
<p><strong>Имам диабет или друго заболяване, пречка ли е?</strong><br>Общите заболявания сами по себе си не означават пречка. Оценява се дали са контролирани, какви лекарства се приемат и при нужда становището на съответния лекар. За някои лекарствени групи може да е нужна допълнителна оценка.</p>
<p><strong>Какво става, ако имплантът не се захване?</strong><br>Загуба на имплант може да настъпи рано или късно и причините са различни. След оценка на находките се обсъждат повторно лечение, изчакване на зарастването на областта или алтернативни възможности. Не се следва един и същ път при всеки случай.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт пригодността за имплант се определя чрез съвместна оценка на клиничния преглед, находките от образната диагностика и протетичните нужди. MSc. Dt. Mehmet Taş е завършил Факултета по дентална медицина на Истанбулския университет и е придобил магистратура по орална хирургия и имплантология в Университета UniCamillus в Италия.</p>
<p><a href="/bg/implant/">Лечение с импланти</a> · <a href="/bg/agiz-cerrahisi-uygulamalari/">Орална хирургия</a> · <a href="/bg/zirkonyum-dis-kaplama/">Циркониеви корони</a> · <a href="/bg/iletisim">Час и контакти</a></p>',
'Възможности за дентални импланти при липсващи зъби; преглед, оценка на костта, етапи на лечението и период на зарастване.',
'Дентални импланти | MSc. Dt. Mehmet Taş',
'BG' FROM treatments WHERE link = 'dental-implant-tedavisi';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Орална хирургия',
'<p>Процедурите по орална хирургия изискват клинична и рентгенова оценка на зъбите, челюстната кост и околните тъкани. Приложеният метод, обхватът на процедурата и периодът на зарастване се планират индивидуално. Dt. Mehmet Taş е придобил магистратура по орална хирургия и имплантология в Университета UniCamillus в Италия.</p>
<h2>Обхват</h2><p>В тази област се разглеждат оценката на ретинирани зъби, хирургичната екстракция, резекцията на върха на корена, увеличаването на костния обем, синус лифтът и <a href="/bg/dental-implant-tedavisi/">имплантологичната хирургия</a>. Всички процедури се извършват в нашата клиника от MSc. Dt. Mehmet Taş и неговия екип.</p>
<h2>Предоперативна оценка</h2><p>Разпитва се за общи заболявания, приемани лекарства, алергии и риск от кървене; клиничният преглед се оценява заедно с панорамна или триизмерна снимка. Анатомичните съседства (синус, нервен канал) са основата на планирането.</p>
<h2>Ретиниран мъдрец</h2><p>Причина за екстракция могат да бъдат болка, повтаряща се инфекция, увреда на съседния зъб, съмнение за кистозна формация или зони, които не могат да се почистват. Не всеки ретиниран зъб се вади; решението се взема заедно след преглед и образна диагностика.</p>
<h2>Планиране на хирургичната екстракция</h2><p>Подходящият хирургичен достъп се определя според позицията на зъба, строежа на корена, отношението му към костта и анатомичните образувания; процедурата се извършва под местна упойка.</p>
<h2>Период на зарастване</h2><p>Обясняват се рецептата и препоръките за грижа: притискане с марля за посоченото от лекаря време, охлаждане отвън, избягване на тютюн и алкохол, мека храна и почивка през първите дни, предпазване на областта и редовна орална хигиена. При необичайни прояви трябва да се потърси клиниката.</p>
<h2>Обясняване на рисковете</h2><p>Оток, болка, кървене, инфекция, временно ограничение на движенията и рискове, свързани с анатомичната близост, се обясняват индивидуално преди процедурата.</p>
<h2>Често задавани въпроси</h2>
<p><strong>Трябва ли всеки мъдрец да се вади?</strong><br>Не. Екстракция се обсъжда при болка, повтаряща се инфекция, увреда на съседния зъб, съмнение за киста или позиция, която не позволява почистване. При зъби без оплаквания и подлежащи на проследяване може да се предпочете наблюдение.</p>
<p><strong>Колко трае процедурата и в колко посещения приключва?</strong><br>Зависи от позицията на зъба, строежа на корена и отношението му към костта. Повечето процедури приключват в едно посещение; при обширни случаи планирането може да е различно. Срокът се обяснява след преглед и образна диагностика.</p>
<p><strong>Ще има ли оток след това?</strong><br>Оток, чувствителност и ограничение при дъвчене след хирургична процедура са очаквани прояви и обикновено са изразени през първите дни. При нарастваща болка, температура, обширен оток или затруднено преглъщане и дишане трябва да се потърси помощ без забавяне.</p>
<p><strong>Какво мога да ям след процедурата?</strong><br>През първия период се предпочитат меки и хладки храни, които не натоварват областта. Препоръчва се да се избягват много горещи храни, пиене със сламка, тютюн и алкохол. Подробните препоръки се дават индивидуално след процедурата.</p>
<p><strong>Приемам кръворазреждащо лекарство, възможна ли е процедурата?</strong><br>Непременно съобщете приеманите лекарства. Кръворазреждащите лекарства не бива да се спират без лекарска препоръка. При нужда планирането се прави със становището на съответния лекар.</p>
<p><strong>Трябва ли да се свалят конците?</strong><br>Зависи от вида на използвания конец; някои се разграждат сами, а други се свалят на контролен преглед. Кой вид е използван и кога е контролата, се съобщава след процедурата.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт нуждата от орална хирургия се оценява чрез клиничен преглед и необходимите образни методи.</p>
<p><a href="/bg/cerrahi/">Орална и лицево-челюстна хирургия</a> · <a href="/bg/dental-implant-tedavisi/">Дентални импланти</a> · <a href="/bg/kanal-tedavisi/">Кореново лечение</a> · <a href="/bg/iletisim">Час и контакти</a></p>',
'Разгледайте прегледа, планирането и периода на зарастване при ретиниран мъдрец, хирургична екстракция и увеличаване на костния обем.',
'Орална хирургия | MSc. Dt. Mehmet Taş',
'BG' FROM treatments WHERE link = 'agiz-cerrahisi-uygulamalari';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Индивидуален дизайн на усмивката',
'<p>Дизайнът на усмивката не е единична процедура, която променя само цвета или формата на зъбите. Това е индивидуален процес на планиране, при който заедно се оценяват зъбите, венците, устните, пропорциите на лицето и оклузалните отношения.</p>
<h2>Какво е дизайн на усмивката?</h2>
<p>При дизайна на усмивката естетичните очаквания не се разглеждат сами по себе си; заедно с тях се оценяват оралното здраве, дъвкателната функция, запазването на зъбната тъкан и естественият вид. Целта е резултат, хармоничен с лицето и устойчив във времето.</p>
<h2>Какво се оценява?</h2>
<ul>
<li>Цвят, форма и пропорции на зъбите</li>
<li>Нива на венците и отношение устни–зъби</li>
<li>Линия на усмивката и пропорции на лицето</li>
<li>Подреждане на зъбите и оклузални отношения</li>
<li>Наличните в устата обтурации и възстановявания</li>
</ul>
<h2>Дигитално планиране</h2>
<p>При подходящи случаи триизмерният запис, направен с интраорален скенер, подпомага планирането и изработването на възстановяванията. Дигиталното планиране е прогностичен инструмент; то не съдържа ангажимент резултатът да бъде идентичен.</p>
<h2>Възможни лечения</h2>
<p>Процедурите, които могат да произтекат от плана, се различават при всеки: <a href="/bg/dis-beyazlatma/">избелване</a>, бондинг, фасети, E.max, <a href="/bg/zirkonyum-dis-kaplama/">циркониеви корони</a>, оформяне на венците, ортодонтска оценка и възстановяване на липсващи зъби. Кои процедури са подходящи, се определя при прегледа.</p>
<h2>Ход на лечението</h2>
<ol>
<li>Преглед и обсъждане на очакванията</li>
<li>Снимки и дигитални записи</li>
<li>Оценка на оралното здраве и оклузията</li>
<li>Обясняване на алтернативите</li>
<li>Предварителен преглед при подходящи случаи</li>
<li>Изпълнение</li>
<li>Контролни часове</li>
</ol>
<h2>Естествен вид</h2>
<p>Естественият вид се постига чрез хармонични с лицето пропорции на зъбите, подходяща повърхностна текстура, светлопропускливост и балансирана линия на усмивката. Един стандартен вид не се прилага при всички.</p>
<h2>Пригодност</h2>
<p>При активен кариес, заболяване на венците или функционален проблем може да се наложи те да бъдат лекувани преди естетичните процедури. Пригодността се определя чрез оценка на зъбите, венците, оклузията и общото орално здраве.</p>
<h2>Hollywood Smile</h2>
<p>Hollywood Smile не е стандартен пакет; това е популярен израз, описващ по-подчертани естетични промени. Не при всеки се прилагат една и съща процедура, една и съща дължина на зъбите и един и същ цвят.</p>
<h2>Често задавани въпроси</h2>
<p><strong>Дизайнът на усмивката една процедура ли е?</strong><br>Не. Дизайнът на усмивката е процес на планиране; от него могат да произтекат различни процедури като избелване, бондинг, фасети, цирконий, оформяне на венците или ортодонтска оценка. Кои са подходящи, се определя при прегледа.</p>
<p><strong>Трябва ли да се изпиляват зъбите ми?</strong><br>Изпиляване не е нужно при всеки план. В някои случаи са достатъчни по-щадящи възможности като избелване или бондинг. Обемът на подготовката зависи от настоящата структура на зъба, основния цвят, целевата форма и избрания материал.</p>
<p><strong>Мога ли да видя резултата предварително?</strong><br>При подходящи случаи дигиталното планиране и предварителният преглед позволяват да се добие представа за възможния резултат. Предварителният преглед е инструмент за планиране; той не е ангажимент за идентичен резултат.</p>
<p><strong>Колко продължава процесът?</strong><br>Зависи от обхвата на плана, необходимите подготвителни лечения и лабораторния етап. При активен кариес или заболяване на венците първо се налага лечението им, което също влияе върху срока.</p>
<p><strong>При усмивка венците ми се виждат много, може ли и това да се планира?</strong><br>Нивата на венците, подвижността на устната и дължината на зъбите са част от оценката. При подходящи случаи оформянето на венците може да влезе в плана; решението се взема според клиничните и рентгеновите находки.</p>
<p><strong>Ще изглежда ли резултатът естествено?</strong><br>Естественият вид се постига чрез хармонични с лицето пропорции на зъбите, подходяща повърхностна текстура, светлопропускливост и балансирана линия на усмивката. Резултатът зависи от индивидуалните условия и не се прилага един стандартен вид.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт възможностите за дизайн на усмивката се определят чрез съвместна оценка на оралното здраве, запазването на зъбната тъкан, дъвкателната функция и целите за естествена естетика.</p>
<p><a href="/bg/estetik/">Естетична дентална медицина</a> · <a href="/bg/zirkonyum-dis-kaplama/">Циркониеви корони</a> · <a href="/bg/dis-beyazlatma/">Избелване на зъби</a> · <a href="/bg/iletisim">Час и контакти</a></p>',
'При дизайна на усмивката заедно се оценяват зъбите, венците, пропорциите на лицето и оклузията. Научете за дигиталното планиране и хода на процеса.',
'Дизайн на усмивката | Дигитално планиране | MSc. Dt. Mehmet Taş',
'BG' FROM treatments WHERE link = 'gulus-tasarimi';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Циркониеви корони',
'<p>Циркониевите корони са керамични възстановявания, предлагащи различни възможности за материали по отношение на здравина, биосъвместимост и естествен вид. Не за всеки зъб са подходящи един и същ материал или една и съща технология на изработка; решението се взема според клиничния преглед и индивидуалните нужди.</p>
<h2>Какво е циркониева корона?</h2>
<p>Това е керамично възстановяване на основата на циркониев диоксид, което обхваща видимата част на зъба. Целта е чрез индивидуално планиране да се възстановят загубената форма, дъвкателната функция и естетиката.</p>
<h2>В кои случаи се обсъжда?</h2>
<ul>
<li>Голяма загуба на тъкан и обширни възстановявания</li>
<li>Счупени или износени зъби</li>
<li>Промяна на цвета и формата</li>
<li>Нужда от мост</li>
<li>Нужда от възстановяване върху <a href="/bg/dental-implant-tedavisi/">имплант</a></li>
</ul>
<h2>Предварителна оценка</h2>
<p>Заедно се оценяват здравето на зъбите и венците, оставащата зъбна тъкан, оклузията, навикът за стискане и скърцане, естетичните очаквания и алтернативните лечения. Здравата зъбна тъкан се запазва доколкото е възможно; короната не се представя като единствена възможност. Възможности като бондинг, инлей/онлей, фасети или E.max се обясняват според показанията.</p>
<h2>Дигитален работен процес</h2>
<ol>
<li>Преглед и снемане на записи</li>
<li>Необходима подготовка</li>
<li>Интраорален скан или отпечатък</li>
<li>Дигитален дизайн и проба</li>
<li>Изработка</li>
<li>Проверка на прилягането, оклузията и естетиката</li>
<li>Поставяне</li>
</ol>
<h2>Монолитна и слоеста възможност</h2>
<p>Монолитният цирконий се изработва от едно парче и е насочен към здравината. При слоестия подход естетичната повърхностна керамика позволява подобряване на цвета, текстурата и поведението на светлината. Изборът се прави според позицията на зъба и натоварването върху него.</p>
<h2>Разлика между цирконий и E.max</h2>
<p>Цирконият предлага различни възможности за здравина и светлопропускливост; литиевият дисиликат (известен като E.max) може да се отличи със светлопропускливостта си особено в избрани естетични зони. Изборът се прави според позицията на зъба и условията на натоварване.</p>
<table>
<thead><tr><th>Критерий</th><th>Цирконий</th><th>E.max / литиев дисиликат</th></tr></thead>
<tbody>
<tr><td>Силна страна</td><td>Възможности за здравина и широко поле на приложение</td><td>Висока светлопропускливост и естетична характеризация</td></tr>
<tr><td>Бележка за планиране</td><td>Включва задния участък, мостовете и конструкциите върху импланти; видът материал се избира според естетичните изисквания.</td><td>Може да се обсъжда особено в избрани случаи в предния участък и при единични зъби.</td></tr>
<tr><td>Критерий за решение</td><td colspan="2">Нито един материал не е по-добър за всички. Определящи заедно са зъбната тъкан, позицията, силата на оклузията, основният цвят, обхватът на възстановяването и естетичната цел.</td></tr>
</tbody>
</table>
<h2>Как се планира естественият вид?</h2>
<p>Заедно се оценяват цветът на съседните зъби, повърхностната текстура, прозрачността, венечният ръб, пропорциите на зъбите, линията на усмивката и видът под светлина. За цялостен естетичен план вижте също страницата <a href="/bg/gulus-tasarimi/">дизайн на усмивката</a>.</p>
<h2>Грижа и контролни прегледи</h2>
<p>Ежедневното четкане, интерденталното почистване, поддържането на здравето на венците и редовните прегледи влияят пряко върху дългосрочния резултат. При навик за стискане и скърцане може да се обсъди предпазна шина.</p>
<h2>Често задавани въпроси</h2>
<p><strong>Колко трае циркониевата корона?</strong><br>Не се дава фиксиран срок или гаранция за употреба. Върху дългосрочния резултат влияят изборът на материал, подготовката, оклузията, оралната хигиена, навикът за стискане и редовните прегледи.</p>
<p><strong>Изглежда ли цирконият естествено?</strong><br>С правилен цвят, повърхностна текстура, дебелина и лабораторна характеризация може да се доближи до естествения вид; резултатът зависи от индивидуалните условия.</p>
<p><strong>Трябва ли зъбът да се изпилява?</strong><br>Обемът на необходимата подготовка зависи от настоящата структура на зъба и избраното възстановяване. По-щадящите алтернативи се оценяват при прегледа.</p>
<p><strong>Цирконий или E.max?</strong><br>Това решение не се взема само по естетични съображения. Заедно се оценяват позицията на зъба, оставащата тъкан, оклузалното натоварване, основният цвят и дизайнът на възстановяването.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт пригодността за циркониева корона се определя чрез съвместна оценка на оставащата зъбна тъкан, здравето на венците, оклузалните отношения и естетичните очаквания.</p>
<p><a href="/bg/estetik/">Естетична дентална медицина</a> · <a href="/bg/gulus-tasarimi/">Индивидуален дизайн на усмивката</a> · <a href="/bg/dental-implant-tedavisi/">Дентални импланти</a> · <a href="/bg/iletisim">Час и контакти</a></p>',
'В кои случаи се обсъждат циркониевите корони? Разгледайте дигиталното планиране, естествения вид, разликата с E.max и препоръките за грижа.',
'Циркониеви корони | MSc. Dt. Mehmet Taş',
'BG' FROM treatments WHERE link = 'zirkonyum-dis-kaplama';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Кореново лечение',
'<p>Целта на кореновото лечение е зъб, чиято пулпа е необратимо увредена или инфектирана, да бъде запазен в устата, когато това е възможно. Решението за лечение не се взема само въз основа на болката; то произтича от съвместната оценка на прегледа, тестовете на пулпата и находките от образната диагностика.</p>
<p>В нашата клиника кореновите лечения се извършват от нашия специалист по ендодонтия <strong>под увеличение с лупа</strong>. Повторното лечение на вече лекуван корен (ретретмент) и при нужда резекцията на върха на корена се провеждат в същия обхват.</p>
<h2>Какво е кореново лечение?</h2>
<p>Това е почистване, оформяне, дезинфекция и запълване с подходящ материал на кореновите канали, когато пулпата на зъба е необратимо увредена или инфектирана.</p>
<h2>В кои случаи се обсъжда?</h2>
<p>Дълбок кариес, травма, пукнатина или фрактура, възпаление или некроза на пулпата, признаци на инфекция в периапикалните тъкани и някои възстановителни нужди могат да наложат кореново лечение.</p>
<h2>Какви могат да бъдат признаците?</h2>
<p>Възможни са спонтанна или нощна болка, продължителна чувствителност към топло и студено, болка при дъвчене, оток, промяна в цвета на зъба или секрет от венеца. Някои зъби не дават никакви признаци; затова редовните прегледи са важни.</p>
<h2>Диагноза и планиране</h2>
<p>Заедно се тълкуват историята на болката, клиничният преглед, тестовете на пулпата, находките от перкусия и палпация, оценката на венците и необходимите рентгенови снимки. Решение не се взема само по един признак.</p>
<p><strong>Важна информация:</strong> антибиотикът не замества механичното почистване на инфектирания коренов канал. Нуждата от медикамент се преценява отделно от лекаря при състояния като общи прояви или риск от разпространение.</p>
<h2>Как протича лечението?</h2>
<ol>
<li>Местна упойка и изолация</li>
<li>Изготвяне на достъпната кухина</li>
<li>Определяне на работната дължина и анатомията на каналите</li>
<li>Почистване, оформяне и промиване (иригация)</li>
<li>Запълване на каналите</li>
<li>Коронарно уплътняване и проверка</li>
</ol>
<h2>Едно посещение или повече?</h2>
<p>Броят посещения зависи от състоянието на пулпата, признаците на инфекция, анатомията на каналите, нуждата от повторно лечение и клиничните условия. Преди прегледа не се поема ангажимент за фиксиран брой посещения.</p>
<h2>Повторно кореново лечение</h2>
<p>При продължаващи признаци, пропускане, пропуснат канал, недостатъчно запълване или съмнение за нова инфекция може да се обсъди отстраняване на старото коренопълнене и повторно лечение. Тази процедура също се извършва в нашата клиника от специалиста по ендодонтия.</p>
<h2>Възстановяване отгоре и проследяване</h2>
<p>Дали върху зъб след кореново лечение е нужна обтурация, онлей или корона, се определя според оставащата зъбна тъкан, риска от пукнатина, позицията на зъба и дъвкателното натоварване. Провежда се клинично и при нужда рентгеново проследяване.</p>
<table>
<thead><tr><th>Възможност</th><th>Кога може да се обсъжда?</th><th>Бележка за планиране</th></tr></thead>
<tbody>
<tr><td>Пряка композитна обтурация</td><td>Достатъчно здрава тъкан и ограничена загуба на материя</td><td>Важни са коронарното уплътняване и проверката на оклузията.</td></tr>
<tr><td>Онлей / овърлей</td><td>Избрани случаи, изискващи покриване на туберкулите, но без нужда от пълно околовръстно покритие</td><td>Може да се обсъжда като адхезивна възможност, щадяща оставащите тъкани.</td></tr>
<tr><td>Пълна корона</td><td>Голяма загуба на материя, риск от пукнатина или наличните възстановителни условия</td><td>Не е автоматично задължение при всеки зъб с кореново лечение. <a href="/bg/zirkonyum-dis-kaplama/">Циркониевата корона</a> е една от възможностите.</td></tr>
</tbody>
</table>
<p>Видът възстановяване се избира индивидуално след прегледа, чрез оценка на оставащата здрава тъкан, позицията на зъба, оклузалното натоварване, риска от пукнатина и условията за изолация.</p>
<h2>Често задавани въпроси</h2>
<p><strong>Болезнено ли е кореновото лечение?</strong><br>С местна упойка се цели комфорт при процедурата; върху преживяването могат да влияят степента на възпалението и индивидуалните условия. Категорична гаранция за безболезненост не се дава.</p>
<p><strong>Нормална ли е болката след лечението?</strong><br>През първите дни е възможна чувствителност при дъвчене. При нарастваща болка, изразен оток, температура или затруднено преглъщане и дишане трябва незабавно да се потърси клиниката.</p>
<p><strong>Нужна ли е корона при всеки зъб с кореново лечение?</strong><br>Не. Възстановяването може да е обтурация, онлей или корона според оставащата тъкан, зъбната група, риска от пукнатина и функционалното натоварване.</p>
<p><strong>Какво се прави, ако лечението е неуспешно?</strong><br>Според диагнозата може да се обсъдят повторно кореново лечение, резекция на върха на корена или екстракция; не всяка възможност е подходяща за всеки зъб.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт нуждата от кореново лечение се определя чрез съвместна оценка на клиничния преглед, тестовете на пулпата и находките от необходимата образна диагностика.</p>
<p><a href="/bg/agiz-dis-sagligi/">Орално и дентално здраве</a> · <a href="/bg/zirkonyum-dis-kaplama/">Циркониеви корони</a> · <a href="/bg/agiz-cerrahisi-uygulamalari/">Орална хирургия</a> · <a href="/bg/iletisim">Час и контакти</a></p>',
'В кои случаи се прилага кореново лечение? Разгледайте признаците, диагнозата, етапите на лечение и възможностите за възстановяване след него.',
'Кореново лечение | Етапи и след него | MSc. Dt. Mehmet Taş',
'BG' FROM treatments WHERE link = 'kanal-tedavisi';

INSERT INTO treatments_description (treatment_id, title, description, seo_description, seo_title, language)
SELECT id, 'Кариес и композитна обтурация',
'<p>Композитната обтурация може да се използва за възстановяване на зъбна тъкан, загубена поради кариес, фрактура или старо възстановяване, с адхезивен материал в цвета на зъба. Не всяка промяна в цвета изисква обтурация; решението се взема според активността на лезията, дълбочината ѝ и възможността за почистване.</p>
<h2>Какво е зъбен кариес?</h2>
<p>Зъбният кариес е процес на загуба на минерали, в който заедно участват биофилмът, ферментируемите въглехидрати, времето, слюнката и индивидуалните рискови фактори. Ранните лезии не винаги са кавитирани.</p>
<p><img src="/assets/uploads/images/ts12-curugun-ilerleyisi.webp" alt="Схема в разрез, показваща напредването на кариеса към емайла, дентина и пулпата" loading="lazy"  /></p>
<h2>Признаци</h2>
<p>Възможни са чувствителност към студено, топло или сладко, болка при дъвчене, засядане на храна или видима промяна в цвета. Някои апроксимални кариеси обаче могат да напредват без никакви признаци; затова редовният преглед е важен.</p>
<h2>Клинична и рентгенова оценка</h2>
<p>Изследват се видът на повърхността и възможността за почистването ѝ, наличието на кавитация, съседните зъби, старите възстановявания и близостта до пулпата. При нужда към оценката се добавя байтуинг или периапикална рентгенова снимка.</p>
<p><img src="/assets/uploads/images/ts12-klinik-ve-radyografik-degerlendirme.webp" alt="Оценка на кариеса чрез клиничен преглед и рентгенова снимка" loading="lazy"  /></p>
<h2>План на лечение</h2>
<p>При ранни некавитирани лезии могат да са достатъчни контрол на риска, флуорид и наблюдение. При лезии, които не могат да се почистват или водят до структурна загуба, се обсъжда щадящо възстановително лечение. Целта не е само отстраняване на потъмнялата тъкан; тя е контрол на кариесната активност, защита на пулпата и запазване на здравата зъбна тъкан, доколкото е възможно.</p>
<h2>Ход на композитната обтурация</h2>
<ol>
<li>Избор на цвят и изолация</li>
<li>Контролирано отстраняване на кариозната тъкан</li>
<li>Адхезивни процедури</li>
<li>Поставяне на композита на слоеве</li>
<li>Проверка на контактната точка, анатомията и оклузията</li>
<li>Финиране и полиране</li>
</ol>
<p><img src="/assets/uploads/images/ts12-kompozit-dolgu-asamalari.webp" alt="Схематична рисунка, показваща етапите на адхезивната композитна обтурация" loading="lazy"  /></p>
<h2>Дълбок кариес и пулпа</h2>
<p>При близост до пулпата заедно се оценяват историята на болката, тестовете за виталност, рентгеновите находки и оставащата зъбна тъкан. В различни ситуации могат да се обсъдят селективно отстраняване на кариеса, процедура за защита на пулпата или <a href="/bg/kanal-tedavisi/">кореново лечение</a>.</p>
<p><img src="/assets/uploads/images/ts12-dolgu-ve-kanal-kapsam-farki.webp" alt="Сравнение, показващо разликата в обхвата между обтурация и кореново лечение" loading="lazy"  /></p>
<h2>Периодът след процедурата</h2>
<p>До преминаване на упойката се препоръчва внимание при хранене. Възможна е краткотрайна чувствителност; при висок контакт, продължителна спонтанна болка или болка при дъвчене се прави контролен преглед.</p>
<h2>Грижа и проследяване</h2>
<p>Важни са четкането, интерденталното почистване, храненето и планът за флуорид според риска от кариес, както и редовните прегледи. Проследяват се ръбът на обтурацията, контактната точка, изтриването, фрактурите и рискът от вторичен кариес.</p>
<h2>Възстановителни възможности според загубата на тъкан</h2>
<table>
<thead><tr><th>Възможност</th><th>Обхват</th><th>Бележка за планиране</th></tr></thead>
<tbody>
<tr><td>Пряка композитна обтурация</td><td>Възстановяване на загубената тъкан в устата с адхезивен материал</td><td>Може да бъде щадяща възможност при ограничена и подлежаща на изолация загуба на тъкан.</td></tr>
<tr><td>Инлей / онлей</td><td>Индиректно възстановяване, изработено в лаборатория или дигитално</td><td>При по-голяма загуба на материя може да се обсъжда според опората на оставащите стени и туберкули.</td></tr>
<tr><td>Корона</td><td>Възстановяване, което покрива по-обхватно короната на зъба</td><td>Може да се обсъжда при голяма структурна загуба или риск от фрактура; не е нужна при всеки кариозен зъб. <a href="/bg/zirkonyum-dis-kaplama/">Циркониевата корона</a> е една от възможностите.</td></tr>
<tr><td>Кореново лечение и възстановяване</td><td>Лечение на каналната система, ако пулпата е необратимо засегната или некротична</td><td>Решението не се взема само по вида на кариеса; то се основава на признаците, тестовете и рентгеновите находки.</td></tr>
</tbody>
</table>
<h2>Често задавани въпроси</h2>
<p><strong>Всеки кариес ли причинява болка?</strong><br>Не. Особено ранните или апроксималните лезии може да не дават признаци. Прегледът и при нужда рентгеновата снимка осигуряват оценка, която не се основава само на болката.</p>
<p><strong>Всяко потъмняло място кариес ли е?</strong><br>Не. Оцветяването може да е спряла лезия, анатомия на фисура или ефект от старо възстановяване. Заедно се оценяват активността, структурата на повърхността и находките от образната диагностика.</p>
<p><strong>Нормална ли е чувствителността след обтурация?</strong><br>Възможна е краткотрайна чувствителност; значение могат да имат дълбочината, близостта до пулпата и оклузията. При засилваща се, спонтанна или продължителна болка е необходим контролен преглед.</p>
<p><strong>Колко трае композитната обтурация?</strong><br>Не се дава фиксиран срок или гаранция за употреба. Върху резултата влияят размерът и позицията на обтурацията, изолацията, оклузията, навикът за стискане, грижата и рискът от кариес.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт нуждата от лечение на кариес и композитна обтурация се определя чрез съвместна оценка на клиничния преглед, необходимите рентгенови снимки, състоянието на пулпата, оклузалните отношения и риска от кариес.</p>
<p><a href="/bg/agiz-dis-sagligi/">Орално и дентално здраве</a> · <a href="/bg/kanal-tedavisi/">Кореново лечение</a> · <a href="/bg/zirkonyum-dis-kaplama/">Циркониеви корони</a> · <a href="/bg/iletisim">Час и контакти</a></p>',
'Как се разпознава зъбният кариес? Научете за клиничната и рентгеновата оценка, етапите на композитната обтурация и подхода при дълбок кариес.',
'Кариес и композитна обтурация | MSc. Dt. Mehmet Taş',
'BG' FROM treatments WHERE link = 'dis-curugu-kompozit-dolgu';

